// Generated by toolbox — the animation timeline.
// Do not edit by hand: change the SkSL Shader node and export again.

import { evaluateTrack, ticksAt, type TimelineTrack } from "./toolbox-timeline";
import { P_scale, P_drift_x, P_contrast } from "./procedural";

export const TIMELINE = {
  fps: 60,
  ticksPerFrame: 1000,
  durationTicks: 300000,
  durationSec: 5,
} as const;

export const CANVAS = { width: 512, height: 512 } as const;

// c2: Color glow.color (3 keys, oklab)
const T_c2: TimelineTrack = {"kind":"color","colorSpace":"oklab","quantize8":true,"alpha":1,"keys":[{"tick":0,"value":[1,0.47843137254901963,0.27058823529411763,1],"easing":"easeInOutQuad"},{"tick":150000,"value":[1,0.23921568627450981,0.5450980392156862,1],"easing":"easeInOutQuad"},{"tick":300000,"value":[1,0.47843137254901963,0.27058823529411763,1],"easing":"linear"}]};

// Every uniform the shader declares, at `seconds` on the toolbox timeline.
// width/height are the canvas size in points (iResolution.xy).
export function sampleUniforms(seconds: number, width: number, height: number) {
  "worklet";
  const tick = ticksAt(seconds, TIMELINE.fps, TIMELINE.ticksPerFrame);
  return {
    iResolution: [width, height, 1],
    iTime: seconds,
    scale: P_scale(tick), // procedural: Expression scale_expr ← LFO wob
    octaves: 4, // static (channel row)
    persistence: 0.5, // static (channel row)
    lacunarity: 2, // static (channel row)
    drift_x: P_drift_x(tick), // procedural: LFO lfo
    drift_y: 0, // static (channel row)
    contrast: P_contrast(tick), // procedural: Expression contrast_expr ← Scene Time st
    c0: [0.0392156862745098,0.058823529411764705,0.17254901960784313,1], // static (channel row)
    c1: [0.23921568627450981,0.35294117647058826,0.996078431372549,1], // static (channel row)
    c2: evaluateTrack(T_c2, tick), // Color glow.color (3 keys, oklab)
    c3: [1,0.8901960784313725,0.7607843137254902,1], // static (channel row)
  };
}
